                    ></i>
                  </div>
                </div>
                <div class="rside-content-cards" v-if="realData">
                  <el-carousel
                    :autoplay="false"
                    ref="realDataCarousel"
                    indicator-position="none"
                    height="120px"
                    v-if="device && realData && realData.data && ['weather', 'soil'].includes(device.device_type)"
                  >
                    <el-carousel-item
                      v-for="(channels, index) in weatherOrSoilChannels"
                      :key="index"
                    >
                      <div class="iot-channel-list">
                        <div
                          class="real-data-item"
                          v-for="(channel, i) in channels"
                          :key="i"
                        >
                          <div
                            class="real-data-item-box"
                            :class="
                              i ===
                              currentChannelIndex % deviceChannelShowPageSize
                                ? 'active'
                                : ''
                            "
                            @click="changeChannel(i)"
                          >
                            <div class="real-data-item-box-top">
                              <i
                                v-if="channel.icon"
                                class="el-icon"
                                :class="channel.icon"
                              ></i>
                              <span class="channel-name">{{
                                channel.name
                              }}</span>
                            </div>
                            <div class="real-data-item-box-bottom">
                              <span class="channel-value">{{
                                channel.value
                              }}</span>
                              <span class="channel-unit">{{
                                channel.unit
                              }}</span>
                            </div>
                            <div
                              class="real-data-item-box-status"
                              :class="device.device_status"
                            >
                              {{ device.device_status_text }}
                            </div>
                          </div>
                        </div>
                      </div>
                    </el-carousel-item>
                  </el-carousel>
                  <div class="pest-data" v-if="device && 'pest' == device.device_type">
                    <div class="pest-data-left">
                      <div class="pest-data-count">
