                          :preview-src-list="[
                            realData.abstract.result_image,
                            realData.abstract.original_image,
                          ]"
                          lazy
                        ></el-image>
                      </div>
                    </div>
                    <div class="pest-data-right">
                      <div class="pest-data-table">
                        <el-table :data="realData.pest.data">
                          <el-table-column
                            prop="name"
                            label="害虫"
                            align="center"
                          >
                          </el-table-column>
                          <el-table-column
                            prop="number"
                            label="数量"
                            align="center"
                          >
                          </el-table-column>
                        </el-table>
                      </div>
                    </div>
                  </div>
                </div>
                <div class="rside-content-cards" v-else>
                  <el-empty description="暂无数据" />
                </div>
                <div class="rside-content-charts">
                  <div class="rside-content-header">
                    <div class="rside-content-header-title">
                      <span>历史数据分析</span>
                    </div>
                    <!-- <div class="rside-content-header-line"></div> -->
                    <div class="rside-content-header-time-range">
                      <el-date-picker
                        v-model="form.time_range"
                        type="daterange"
                        :picker-options="pickerOptions"
                        range-separator="至"
                        start-placeholder="开始日期"
                        end-placeholder="结束日期"
                        align="right"
                        size="mini"
                        value-format="yyyy-MM-dd"
                        format="yyyy-MM-dd"
                        @change="renderHistoryCharts"
                      >
                      </el-date-picker>
                    </div>
                  </div>
                  <div
                    class="history-charts"
                    v-loading="chartLoading"
                    id="history-charts"
                    v-if="historyDataList.length"
                  ></div>
                  <div class="history-charts" v-else>
                    <el-empty description="暂无数据" />
                  </div>
                </div>
              </div>
            </div>
          </div>
