  </el-dialog>
</template>
 <script>
import { isMobile } from '@/utils/tools'
import * as echarts from 'echarts'
// eslint-disable-next-line no-unused-vars
import {
  getDeviceInfo,
  getDeviceRealData,
  getDeviceHistoryData,
} from '@/api/iot'
export default {
  name: 'MarkerShow',
  components: {},
  directives: {},
  data() {
    return {
      title: '',
      iotInfo: null,
      width: '760px',
      visible: false,
      fullscreen: false,
      dTop: '',
      form: {
        time_range: '',
      },
      pickerOptions: {
        shortcuts: [
          {
            text: '最近一周',
            onClick(picker) {
              const end = new Date()
              const start = new Date()
              start.setTime(start.getTime() - 3600 * 1000 * 24 * 7)
              picker.$emit('pick', [start, end])
            },
          },
          {
            text: '最近一个月',
            onClick(picker) {
              const end = new Date()
              const start = new Date()
              start.setTime(start.getTime() - 3600 * 1000 * 24 * 30)
              picker.$emit('pick', [start, end])
            },
          },
          {
            text: '最近三个月',
            onClick(picker) {
              const end = new Date()
              const start = new Date()
              start.setTime(start.getTime() - 3600 * 1000 * 24 * 90)
              picker.$emit('pick', [start, end])
            },
          },
        ],
      },
      device: null,
      realDataList: [],
      realData: null,
      chartLoading: false,
      deviceChannelShowPageSize: isMobile() ? 2 : 4,
      currentChannelIndex: 0,
      historyDataList: [],
      deviceLoading: false,
      historyChart: null,
      pestRealList: [],
    }
  },
  computed: {
    isMobile() {
      return isMobile()
    },
    weatherOrSoilChannels() {
      const channels = this.realData.data
      const page = this.deviceChannelShowPageSize
      const carouselItems = []
      const pageSize = Math.ceil(channels.length / page)
      // console.log('pageSize:', pageSize)
      for (let i = 0; i < pageSize; i++) {
        const index = i * page
        const sliceChannels = channels.slice(index, index + page)
        carouselItems.push(sliceChannels)
      }
      // console.log('carouselItems:', carouselItems)
      return carouselItems
    },
  },
  methods: {
    open(device, dialogWidth = '760px', fullscreen = false, dTop = '2vh') {
      this.form.time_range = [
        this.formatDate(new Date()),
        this.formatDate(new Date()),
      ]
      this.device = device
      this.title = this.device.device_name
      this.fullscreen = 'pest' === this.device ? true : fullscreen
      this.dTop = dTop
      this.width = dialogWidth
      this.getDeviceRealData()
      this.visible = true
      this.$nextTick(() => {
        window.addEventListener('resize', () => {
          if (this.historyChart) {
            this.historyChart.resize()
          }
        })
        this.renderHistoryCharts()
      })
    },
    formatDate(date) {
      const year = date.getFullYear()
      const month = String(date.getMonth() + 1).padStart(2, '0') // 补齐两位
      const day = String(date.getDate()).padStart(2, '0') // 补齐两位
      return `${year}-${month}-${day}`
    },
    async getDeviceRealData() {
      const res = await getDeviceRealData(this.device.device_full_id)
      console.log('deviceRealData:', res)
      this.realData = res
    },
    async getDeviceHistoryData() {
      const res = await getDeviceHistoryData(this.device.device_full_id, {
        start_time: this.form.time_range[0],
        end_time: this.form.time_range[1],
      })
      console.log('getDeviceHistoryData:', res)
    },
    async getDeviceInfo() {
      this.deviceLoading = true
      this.device = await getDeviceInfo(this.device.device_full_id)
      this.deviceLoading = false
    },
    prevRealData() {
      this.$refs.realDataCarousel.prev()
      const activeIndex = this.$refs.realDataCarousel.activeIndex
      console.log('activeIndex:', activeIndex)
      const channelIndex = activeIndex * this.deviceChannelShowPageSize
      console.log('channelIndex:', channelIndex)
      this.changeChannel(channelIndex)
    },
    nextRealData() {
      this.$refs.realDataCarousel.next()
      const activeIndex = this.$refs.realDataCarousel.activeIndex
      console.log('activeIndex:', activeIndex)
      const channelIndex = activeIndex * this.deviceChannelShowPageSize
      console.log('channelIndex:', channelIndex)
      this.changeChannel(channelIndex)
    },
    changeChannel(index) {
      this.currentChannelIndex = index

      this.renderHistoryCharts()
    },
    async renderHistoryCharts() {
      this.chartLoading = true
      console.log('this.form:', this.form)
      const {data} = await getDeviceHistoryData(
        this.device.device_full_id,
        {
          start_time: this.form.time_range[0],
          end_time: this.form.time_range[1],
          channel_num: this.currentChannelIndex + 1,
          format: 'chart',
          type: 9,
        }
      )
      const {xAxisData, seriesData} = data
      this.chartLoading = false
      this.historyDataList = seriesData
      if (!seriesData.length) {
        return
      }

      this.$nextTick(() => {
        if (!this.historyChart) {
          this.historyChart = echarts.init(
            document.getElementById('history-charts')
          )
        }

        const option = {
          tooltip: {
            trigger: 'axis',
            className: 'brokenLineTooltip',
            backgroundColor: 'rgba(13,29,39,0.7)',
            textStyle: {
              color: '#FFFFFFFF',
            },
          },
          grid: {
            top: '5%',
            left: '0%',
            right: '5%',
            bottom: '4%',
            containLabel: true,
          },
          xAxis: [
            {
              type: 'category',
              color: '#59588D',
              axisLine: {
                show: true,
                color: '#6C8097FF',
                lineStyle: {
                  type: 'solid',
                  color: '#6C8097FF',
                },
              },
              axisLabel: {
                color: '#CCCCCCFF',
              },
              splitLine: {},
              axisTick: {
                show: false,
              },
              data: xAxisData,
            },
          ],
          yAxis: [
            {
              type: 'value',
              min: 0,
              splitNumber: 4,
              axisLine: {
                show: false,
                lineStyle: {
                  type: 'solid',
                  color: '#6C8097FF',
                },
              },
              axisLabel: {
                show: true,
                textStyle: {
                  color: '#CCCCCCFF',
                },
              },
              axisTick: {
                show: false,
              },
              splitLine: {
                show: true,
                lineStyle: {
                  color: '#A8A8A8FF',
                  type: 'dashed',
                  opacity: 0.1,
                },
              },
            },
          ],
          series: [
            {
              name: '',
              type: 'line',
              smooth: true,
              showAllSymbol: false,
              symbolSize: 20,
              lineStyle: {
                normal: {
                  color: '#FCDE1FFF',
                },
              },
              label: {
                show: false,
                position: 'top',
                textStyle: {
                  color: '#48B3FF',
                },
              },
              tooltip: {
                show: true,
              },
              areaStyle: {
                normal: {
                  color: {
                    colorStops: [
                      {
                        offset: 0,
                        color: '#fcde1f75',
                      },
                      {
                        offset: 0.8,
                        color: '#fcde1f00',
                      },
                    ],
                    x: 0,
                    y: 0,
                    x2: 0,
                    y2: 1,
                    type: 'linear',
                    global: false,
                  },
                  shadowColor: 'rgba(195,230,255,0.1)',
                  shadowBlur: 20,
                },
              },
              data: seriesData,
            },
            {
              name: '',
              type: 'line',
              smooth: true,
              showAllSymbol: false,
              symbolSize: 20,
              lineStyle: {
                normal: {
                  color: '#11c5e2',
                },
              },
              label: {
                show: false,
                position: 'top',
                textStyle: {
                  color: '#48B3FF',
                },
              },
              tooltip: {
                show: true,
              },
              areaStyle: {
                normal: {
                  color: {
                    colorStops: [
                      {
                        offset: 0,
                        color: '#5298A3FF',
                      },
                      {
                        offset: 0.8,
                        color: 'rgba(112,255,60,0)',
                      },
                    ],
                    x: 0,
                    y: 0,
                    x2: 0,
                    y2: 1,
                    type: 'linear',
                    global: false,
                  },
                  shadowColor: 'rgba(195,230,255,0.1)',
                  shadowBlur: 20,
                },
              },
            },
            {
              name: '',
              type: 'line',
              smooth: true,
              showAllSymbol: false,
              symbolSize: 20,
              lineStyle: {
                normal: {
                  color: 'var(--stong-primary-color)',
                },
              },
              label: {
                show: false,
                position: 'top',
                textStyle: {
                  color: '#48B3FF',
                },
              },
              tooltip: {
                show: true,
              },
              areaStyle: {
                normal: {
                  color: {
                    colorStops: [
                      {
                        offset: 0,
                        color: '#1d4b38',
                      },
                      {
                        offset: 0.8,
                        color: 'rgba(23,255,160,0.02)',
                      },
                    ],
                    x: 0,
                    y: 0,
                    x2: 0,
                    y2: 1,
                    type: 'linear',
                    global: false,
                  },
                  shadowColor: 'rgba(195,230,255,0.1)',
                  shadowBlur: 20,
                },
              },
            },
          ],
        }
        this.historyChart.setOption(option)
      })
    },
    parseWeatherAndSoilHistoryData(historyData) {
      const xAxisData = historyData.data.map((m) => m.created_at)
      const channel = this.currentChannelIndex + 1
      const channelNum = `channel_${channel < 10 ? '0' + channel : channel}`
      const seriesData = historyData.data.map((m) => m[channelNum])

      return {
        xAxisData,
        seriesData,
      }
    },
    parsePestHistoryData(historyData) {
      const xAxisData = historyData.times
      const seriesData = historyData.list.map((m) => m.total)

      return {
        xAxisData,
        seriesData,
      }
    },
    onDialogClose() {
      this.$emit('onDialogClose')
      this.realData = null
      if (this.historyChart) {
        this.historyChart.clear()
      }
    },
  },
}
</script>
